def compute(vars):
    operating_cash_flow = vars["v1"]
    investing_cash_flow = vars["v2"]
    if investing_cash_flow == 0:
        return None
    ratio = operating_cash_flow / investing_cash_flow
    return {
        "value": ratio,
        "trace": {
            "operating_cash_flow": operating_cash_flow,
            "investing_cash_flow": investing_cash_flow,
            "output_meta": {"currency": None, "scale": None, "unit": "ratio"}
        }
    }
